/**
 * AsteriaStar platform — Worker entry.
 *
 * Wraps the OpenNext handler (`.open-next/worker.js`, generated by `npm run cf:build`) to keep the
 * response headers the site had on Netlify, where the Next.js Runtime rewrote them on the way out.
 * Static files never reach this code: Workers static assets answers them first, with the headers in
 * `cloudflare/_headers`.
 *
 * What Netlify did, and what is reproduced here (all measured on production before the move):
 *
 * 1. Browser Cache-Control. For GET/HEAD, Netlify moved `s-maxage` and `stale-while-revalidate` off
 *    the browser-facing Cache-Control (into its own CDN header). A prerendered or ISR page therefore
 *    answered `public, max-age=0, must-revalidate`, and a dynamic handler such as /api/v0/search
 *    answered `public, max-age=3600` rather than `…, stale-while-revalidate=86400`. Without this, a
 *    page reaches browsers and shared caches with `s-maxage=31536000`.
 *    Static route handlers (served from the cache without `x-nextjs-prerender`: /api/v0/sources,
 *    /llms.txt, …) were left as their handler set them. Next 16.4 appends its default
 *    `stale-while-revalidate=2592000` (the 30-day expire time) to those; Next 16.2, which Netlify
 *    ran, did not, so that one default directive is removed.
 * 2. A response with no Cache-Control at all (an API 400, a redirect) answered `no-cache`.
 * 3. HSTS and nosniff on every response, including the trailing-slash 308 that the Next.js router
 *    emits before `next.config.ts` headers apply; that redirect also carries its target as a
 *    text/plain body, as Next's did.
 */
import openNext from "../.open-next/worker.js";

export { DOQueueHandler } from "../.open-next/worker.js";

const HSTS = "max-age=63072000";
const NEXT_DEFAULT_EXPIRE = /(^|,)\s*stale-while-revalidate=2592000\s*(?=,|$)/i;

function omitDirectives(value, names) {
  return value
    .split(",")
    .map((part) => part.trim())
    .filter((part) => part && !names.includes(part.split("=")[0].trim().toLowerCase()))
    .join(", ");
}

function browserCacheControl(request, response) {
  if (request.method !== "GET" && request.method !== "HEAD") return null;
  const current = response.headers.get("cache-control");
  if (current === null) return "no-cache";

  const fromCache = response.headers.has("x-opennext-cache");
  const isPage = response.headers.has("x-nextjs-prerender");
  if (fromCache && !isPage) {
    // A static route handler: keep the handler's own policy, minus Next 16.4's added default.
    const cleaned = current.replace(NEXT_DEFAULT_EXPIRE, "").replace(/^\s*,\s*/, "").trim();
    return cleaned === current ? null : cleaned;
  }
  if (!/s-maxage|stale-while-revalidate/i.test(current)) return null;
  return omitDirectives(current, ["s-maxage", "stale-while-revalidate"]) || "public, max-age=0, must-revalidate";
}

const worker = {
  async fetch(request, env, ctx) {
    const response = await openNext.fetch(request, env, ctx);

    const headers = new Headers(response.headers);
    let body = response.body;

    const cacheControl = browserCacheControl(request, response);
    if (cacheControl !== null) headers.set("cache-control", cacheControl);
    if (!headers.has("strict-transport-security")) headers.set("strict-transport-security", HSTS);
    if (!headers.has("x-content-type-options")) headers.set("x-content-type-options", "nosniff");

    const location = headers.get("location");
    if (response.status >= 300 && response.status < 400 && location && !headers.has("content-type")) {
      headers.set("content-type", "text/plain; charset=utf-8");
      body = request.method === "HEAD" ? null : location;
    }

    return new Response(body, { status: response.status, statusText: response.statusText, headers });
  },
};

export default worker;
